import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        long n = s.nextLong();
        long p = (long)(Double.parseDouble(s.next()) * 10000);
        long studied = 0;
        long notStudied = n;

        while (true) {
            long zero = comb3(notStudied);
            long one = comb2(notStudied) * studied;
            long two = comb2(studied) * notStudied;
            long three = comb3(studied);

            long thisP = one + two * 2 + three * 2;
            long left = thisP * 5000;
            long right = p * comb3(n);

            if (left >= right) {
                System.out.println(studied);
                break;
            }

            studied++;
            notStudied--;
        }
    }

    private static long comb2(long x) {
        return x * (x - 1) / 2;
    }

    private static long comb3(long x) {
        return x * (x - 1) * (x - 2) / 6;
    }
}
